entries[306603] = { ["name"] = "Instabile Leere", ["text"] = "Unbegrenzte Reichweite\nSofort\nFeuert ein Leerengeschoss auf einen Ort in der Nähe, das allen Gegnern innerhalb von 6 Metern 20325 Schattenschaden zufügt und sie mit ' Instabilitätskontakt ' belegt.\n\nWenn der Schaden nicht abgefangen wird, wird ' Instabiler Leerenstoß ' ausgelöst, was allen Spielercharakteren 13755 Schattenschaden zufügt, sie 8 Sek. lang mit ' Instabilitätskontakt ' belegt und zum Schweigen bringt.\n\nDanach wird ein weiteres Geschoss auf einen Ort in der Nähe abgefeuert. Dies kann bis zu 5-mal auftreten." }
