entries[306982] = { ["name"] = "Vernichtung", ["text"] = "Wirken in 2 sek.\nVernichtet Spielercharaktere und Kultisten vor dem Zaubernden und verursacht 5 Sek. lang alle 0.25 Sek. 1876 Schattenschaden.\n\nJeder Treffer erhöht den durch 'Vernichtung' verursachten Schaden 6 Sek. lang um 25%. Bis zu 20-mal stapelbar.\n\nVerbraucht 'Geschenk der Leere' und reinigt 'Leerenverderbnis' beim Zaubernden." }
