entries[306984] = { ["name"] = "Eruption der Manie", ["text"] = "1000 Meter Reichweite\nSofort\nPflanzt die Saat der Manie in Ziele. Nach 12 Sek. explodiert diese Saat, fügt Gegnern innerhalb von 10 Metern 14071 Schattenschaden zu und versetzt sie 2 Sek. lang in Furcht.\n\nNicht anvisierte Spielercharaktere, die von der Explosion betroffen sind, verlieren 30 geistige Gesundheit.\n\nDies beschwört 1 Alptraumantigen in der Nähe." }
