entries[307041] = { ["name"] = "Orkanschlag", ["text"] = "Unbegrenzte Reichweite\nSofort\nEntfesselt einen Orkanschlag, der Spielercharakteren innerhalb von 30 Metern 28196 Feuerschaden zufügt und sie zurückstößt sowie allen Spielercharakteren, die weiter als 30 Meter entfernt sind, 14062 Feuerschaden zufügt.\n\nDaraufhin werden Feuerbälle auf die Positionen zufälliger Gegner abgefeuert, die Gegnern innerhalb von 5 Metern um den Einschlag 23450 Feuerschaden zufügen." }
entries[307042] = { ["name"] = "Adaptives Antigen", ["text"] = "Sofort\nDas Alptraumantigen erhält regelmäßig 'Adaptives Antigen', was den verursachten Schaden um 10% erhöht und verhindert, dass die Bewegungsgeschwindigkeit unter 10% der normalen Bewegungsgeschwindigkeit verlangsamt wird.\nDieser Effekt ist stapelbar.\n(3s Abklingzeit)" }
