entries[307044] = { ["name"] = "Alptraumantikörper", ["text"] = "100 Meter Reichweite\nSofort\nErfolgreiche Nahkampfangriffe entziehen dem Ziel Kraft, fügen ihm 3127 Schattenschaden zu und verringern 4 Sek. lang sein Tempo um 3% sowie seine Bewegungsgeschwindigkeit um 3%.\nDieser Effekt ist stapelbar." }
