entries[307046] = { ["name"] = "Elysischer Erlass", ["text"] = "Pakt-Fähigkeit\n100 Meter Reichweite\nSofort\nPlatziert ein kyrianisches Zeichen am Zielort, das sich nach 2 Sek. aktiviert.\n\nEs detoniert, fügt vom Zeichen betroffenen Gegnern (378% der Angriffskraft) Arkan schaden zu und spaltet bis zu 3 geringe Seelenfragmente von ihnen ab. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
