entries[307053] = { ["name"] = "Lavapfützen", ["text"] = "100 Meter Reichweite\nSofort\nLavapfützen formen sich aus intakten Splittern und fügen allen Spielercharakteren, die innerhalb der Pfütze stehen, alle 1 Sek. 10486 Feuerschaden zu.\n\nZusätzlich erhalten Spielercharaktere für jede Lavapfütze, die entsteht, einen Stapel ' Wachsende Hitze '." }
