entries[307057] = { ["name"] = "Dunkler Durchgang", ["text"] = "300 Meter Reichweite\nSofort\nVexionas dunkle Macht reißt ein Portal auf, fügt allen Spielercharakteren 10944 Schattenschaden zu und ermöglicht Kultisten, den Bereich zu betreten." }
