entries[307061] = { ["name"] = "Myzelgeschwür", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin Netz aus sich ausbreitenden Fasern legt sich über die Umgebung, verringert die Bewegungsgeschwindigkeit von Zielen um 75% und verursacht alle 1 Sek. 938 Naturschaden.\n\nDas Netz wird kleiner, wenn die Gesundheit der Myzelzyste sinkt." }
