entries[307070] = { ["name"] = "Durchstöbern", ["text"] = "Wirken in 3 sek.\nReagenzien:\nGeborgene Truhe mit Vorräten\nÖffnet den Behälter und entdeckt einen nutzbaren Ausrüstungsgegenstand für die Beutespezialisierung Eures Charakters." }
entries[307071] = { ["name"] = "Synthese", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 7 tagen)\nJedes Synthesegeschwür regeneriert N'Zoths Gesundheit, stellt alle 2 Sek. 7674 Gesundheit wieder her, absorbiert sämtlichen Schaden und macht ihn immun gegen heilungsverringernde Effekte. Dieser Effekt ist stapelbar." }
