entries[307085] = { ["name"] = "Brennender Wahnsinn", ["text"] = "Unbegrenzte Reichweite\nSofort 1 sek. Abklingzeit\nSolange der Wahnsinn aktiv ist, wird jeder knisternde Splitter, über den Ihr lauft, zerstört und die Dauer von ' Brennender Wahnsinn ' wird dabei verlängert. Jedes Mal, wenn das der Fall ist, wird ein Stapel ' Brennender Wahnsinn ' entfernt." }
