entries[307094] = { ["name"] = "Trank der verhärteten Schatten", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRunenverzierte Phiole , Wachtfackel (3), Ruhmesstieg (3)\nBeruf:\nAlchemie der Schattenlande (100)\nLehrer:\nElixierist Au'pyr\nZone:\nOribos\nKosten:\n4\n50\n\nBenutzen: Verleiht Eurem Körper widerstandfähige Energie, die Eure Rüstung 25 Sek. lang um 747 erhöht. (5 Min Abklingzeit)\n51" }
