entries[307101] = { ["name"] = "Spektralfläschchen der Macht", ["text"] = "Wirken in 2.5 sek.\nReagenzien:\nRunenverzierte Phiole , Nachtschatten (3), Ruhmesstieg (4), Markwurzel (4), Witwenblüte (4), Wachtfackel (4)\nBeruf:\nAlchemie der Schattenlande (160)\nLehrer:\nElixierist Au'pyr\nZone:\nOribos\nKosten:\n14\n50\n\nBenutzen: Erhöht den Primärwert 1 Stunde lang um 190 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n51" }
