entries[307381] = { ["name"] = "Trank des ermächtigten Exorzismus", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRunenverzierte Phiole , Witwenblüte (3), Markwurzel (3)\nBeruf:\nAlchemie der Schattenlande (135)\nLehrer:\nElixierist Au'pyr\nZone:\nOribos\nKosten:\n8\n\nBenutzen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, die Anima des Ziels ausbrechen zu lassen, was allen Gegnern innerhalb von 10 Metern um das Ziel bis zu 3740 Schattenschaden zufügt.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, werden der zusätzliche Schaden und die Reichweite um 20% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\n51" }
entries[307382] = { ["name"] = "Trank des Phantomfeuers", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRunenverzierte Phiole , Markwurzel (3), Ruhmesstieg (3)\nBeruf:\nAlchemie der Schattenlande (125)\nLehrer:\nElixierist Au'pyr\nZone:\nOribos\nKosten:\n7\n\nBenutzen: Eure Angriffe und Zauber haben eine Chance, eine feurige Projektion zum Ziel zu schicken, die ihm 6270 Schattenflammenschaden zufügt.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, wird der zusätzliche Schaden um 10% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\n51" }
entries[307383] = { ["name"] = "Trank des göttlichen Erwachens", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRunenverzierte Phiole , Ruhmesstieg (3), Wachtfackel (3)\nBeruf:\nAlchemie der Schattenlande (125)\nLehrer:\nElixierist Au'pyr\nZone:\nOribos\nKosten:\n7\n\nBenutzen: Eure Heilzauber heilen abhängig von der fehlenden Gesundheit des Ziels um bis zu 11765 Gesundheit mehr.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Einbalsamieröl verstärkt ist, wird die zusätzliche Heilung um 10% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\n51" }
entries[307384] = { ["name"] = "Trank der tödlichen Fixierung", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRunenverzierte Phiole , Witwenblüte (3), Wachtfackel (3)\nBeruf:\nAlchemie der Schattenlande (135)\nLehrer:\nElixierist Au'pyr\nZone:\nOribos\nKosten:\n8\n\nBenutzen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, Euer Ziel mit 'Tödliche Fixierung' zu belegen, was im Verlauf von 8 Sek. 172 Schattenschaden verursacht und bis zu 5-mal stapelbar ist. Beim Erreichen von 5 Stapeln explodiert 'Tödliche Fixierung' und fügt dem Ziel 3946 Schattenschaden zu.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, wird der Explosionsschaden um 10% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\n51" }
