entries[307495] = { ["name"] = "Trank des Phantomfeuers", ["text"] = "Sofort\nCa. 12 Procs pro Minute\nEure Angriffe und Zauber haben eine Chance, eine feurige Projektion zum Ziel zu schicken, die ihm 6270 Schattenflammenschaden zufügt.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, wird der zusätzliche Schaden um 10% erhöht. Hält 25 Sek. lang an." }
entries[307496] = { ["name"] = "Trank des göttlichen Erwachens", ["text"] = "Sofort\nCa. 12 Procs pro Minute\nEure Heilzauber heilen abhängig von der fehlenden Gesundheit des Ziels um bis zu 11765 Gesundheit mehr.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Einbalsamieröl verstärkt ist, wird die zusätzliche Heilung um 10% erhöht. Hält 25 Sek. lang an." }
entries[307497] = { ["name"] = "Trank der tödlichen Fixierung", ["text"] = "Sofort\nCa. 20 Procs pro Minute\nEure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, Euer Ziel mit 'Tödliche Fixierung' zu belegen, was im Verlauf von 8 Sek. 172 Schattenschaden verursacht und bis zu 5-mal stapelbar ist. Beim Erreichen von 5 Stapeln explodiert 'Tödliche Fixierung' und fügt dem Ziel 3946 Schattenschaden zu.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, wird der Explosionsschaden um 10% erhöht. Hält 25 Sek. lang an." }
