entries[307527] = { ["name"] = "Kugelbetriebsanleitung", ["text"] = "Ermöglicht innerhalb von verstörenden Visionen die Nutzung von Verstandswiederherstellungs-\nkugeln. Die Kugeln können alle Verbündeten in der Nähe wieder-\nbeleben und deren geistige Gesundheit wiederherstellen.\n\nEs können von beliebigen Gruppenmitgliedern Verstands-\nwiederherstellungskugeln beschwört werden, bis ein Maximum von 3 in einer Vision erreicht wurde." }
entries[307528] = { ["name"] = "Gabe der Titanen", ["text"] = "Das Besiegen von Gegnern in verstörenden Visionen gewährt eine Chance, 'Gabe der Titanen' zu verleihen, wodurch Tempo und Bewegungsgeschwindigkeit um 60% erhöht werden und der Verlust geistiger Gesundheit aus allen Quellen um 100% verringert wird. Hält 20 Sek. lang an." }
