entries[307559] = { ["name"] = "Blut von N'Zoth", ["text"] = "60 Meter Reichweite\nSofort\nCa. 6 Procs pro Minute\nN'Zoths Blut erhöht die verursachte Heilung des Ziels um 5%. Wenn das Ziel schwer verletzt ist, bildet sich zu Füßen des Ziels eine Lache aus ätzendem Blut." }
